/* Blesscon Candy - order invoice / customer receipt (no backend needed)
   After "Place Order" this opens a styled invoice popup with:
   - "Send PDF on WhatsApp": builds a real PDF receipt (with the Blesscon logo) and hands the
     FILE to WhatsApp through the phone's share sheet. On browsers that cannot share files
     (most desktops) the PDF is downloaded and WhatsApp opens so it can be attached.
   - "Download PDF": saves the same PDF receipt (falls back to print if the PDF cannot be built). */
(function () {
"use strict";
function money(n) {
  var cur = (typeof CFG !== "undefined" && CFG.currency) || "Rs.";
  return cur + " " + Number(n || 0).toLocaleString("en-US");
}
function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}
/* "+92 3413905030" / "0341..." / "0092..." -> "923413905030" (wa.me format) */
function waDigits(phone) {
  var d = String(phone || "").replace(/\D/g, "");
  if (d.indexOf("00") === 0) d = d.slice(2);
  if (d.charAt(0) === "0") d = d.slice(1);
  if (d.length === 10 && d.charAt(0) === "3") d = "92" + d;
  return d;
}
function bizPhone() { return (typeof CFG !== "undefined" && CFG.whatsapp) || "923413905030"; }

function receiptText(o) {
  var L = [];
  L.push("*BLESSCON CANDY - ORDER RECEIPT*");
  L.push("Order: " + o.id + "  |  " + o.date);
  L.push("Customer: " + o.customer.name + (o.customer.phone ? " (" + o.customer.phone + ")" : ""));
  if (o.location) L.push("Deliver to: " + o.location);
  L.push("--------------------------------");
  o.lines.forEach(function (ln, i) {
    L.push((i + 1) + ". " + ln.name);
    L.push("   " + ln.pack + " | " + money(ln.unit) + " x " + ln.qty + " = *" + money(ln.total) + "*");
  });
  L.push("--------------------------------");
  L.push("Subtotal: " + money(o.subtotal));
  if (o.delivery != null) L.push("Delivery: " + money(o.delivery));
  else if (o.deliveryNote) L.push("Delivery: " + o.deliveryNote);
  L.push("*TOTAL PAYABLE: " + money(o.grand) + "*");
  L.push("--------------------------------");
  L.push("Thank you for ordering from Blesscon Candy!");
  L.push("WhatsApp us: +" + bizPhone());
  L.push("www.blessconcandy.com");
  return L.join("\n");
}

/* ---------- PDF receipt (jsPDF, loaded on demand from cdnjs) ---------- */
var JSPDF_SRC = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
var jsPdfP = null;
function loadJsPdf() {
  if (window.jspdf && window.jspdf.jsPDF) return Promise.resolve(window.jspdf.jsPDF);
  if (!jsPdfP) jsPdfP = new Promise(function (res, rej) {
    var s = document.createElement("script");
    s.src = JSPDF_SRC; s.async = true;
    s.onload = function () { (window.jspdf && window.jspdf.jsPDF) ? res(window.jspdf.jsPDF) : rej(new Error("jsPDF missing")); };
    s.onerror = function () { jsPdfP = null; rej(new Error("jsPDF failed to load")); };
    document.head.appendChild(s);
  });
  return jsPdfP;
}
function assetsBase() { return (typeof CFG !== "undefined" && CFG.assets) || "assets/"; }
function logoSrc() { return assetsBase() + "logo.png"; }
/* Same fallback chain the site header uses: local png -> live site -> local svg. Resolves null if none works. */
/* built-in copy of the logo (from favicon.ico): guarantees the PDF always shows the logo even if the files above cannot be read */
var LOGO_FALLBACK = "data:image/png;base64,";
var logoP = null;
function loadLogo() {
  if (logoP) return logoP;
  var remote = (typeof CFG !== "undefined" && CFG.remote) || "https://www.blessconcandy.com/assets/";
  var list = [assetsBase() + "logo.png", remote + "logo.png", assetsBase() + "logo.svg", remote + "logo.svg", LOGO_FALLBACK];
  function tryOne(i) {
    if (i >= list.length) { try { console.warn("Blesscon invoice: logo not found, tried", list); } catch (e) {} return Promise.resolve(null); }
    return new Promise(function (res) {
      var im = new Image();
      im.crossOrigin = "anonymous";
      im.onload = function () {
        try {
          var nw = im.naturalWidth || 600, nh = im.naturalHeight || 240;
          var sc = Math.min(1, 800 / nw), c = document.createElement("canvas");
          c.width = Math.max(1, Math.round(nw * sc)); c.height = Math.max(1, Math.round(nh * sc));
          c.getContext("2d").drawImage(im, 0, 0, c.width, c.height);
          res({ data: c.toDataURL("image/png"), w: c.width, h: c.height });
        } catch (e) { res(null); }
      };
      im.onerror = function () { res(null); };
      im.src = list[i];
    }).then(function (r) { return r || tryOne(i + 1); });
  }
  logoP = tryOne(0);
  return logoP;
}
/* the built-in PDF fonts only cover Latin-1: swap anything else for "?" rather than print garbage */
function pt(s) { return String(s == null ? "" : s).replace(/\s+/g, " ").replace(/[^\x20-\x7E\u00A0-\u00FF]/g, "?").trim(); }

function buildPdf(o) {
  return Promise.all([loadJsPdf(), loadLogo()]).then(function (r) {
    var JsPDF = r[0], logo = r[1];
    var doc = new JsPDF({ unit: "mm", format: "a4" });
    var W = 210, H = 297, M = 14, CW = W - 2 * M;
    var PINK = [233, 30, 99], PINKD = [179, 18, 74], PINKL = [255, 122, 156], INK = [43, 27, 46], MUTED = [111, 93, 115], SOFT = [253, 227, 238], BG = [255, 246, 250], LINE = [243, 219, 230], GOLD = [255, 210, 63], WHITE = [255, 255, 255];
    function fill(c) { doc.setFillColor(c[0], c[1], c[2]); }
    function ink(c) { doc.setTextColor(c[0], c[1], c[2]); }
    function stroke(c) { doc.setDrawColor(c[0], c[1], c[2]); }
    function font(style, size) { doc.setFont("helvetica", style); doc.setFontSize(size); }
    function mix(a, b, t) { return [Math.round(a[0] + (b[0] - a[0]) * t), Math.round(a[1] + (b[1] - a[1]) * t), Math.round(a[2] + (b[2] - a[2]) * t)]; }
    function alpha(v) { try { doc.setGState(new doc.GState({ opacity: v })); } catch (e) { /* older builds: skip transparency */ } }
    function gradBand(x, y, w, h) { var n = 60, sw = w / n; for (var i = 0; i < n; i++) { fill(mix(PINKD, PINKL, i / (n - 1))); doc.rect(x + i * sw, y, sw + 0.35, h, "F"); } }
    var bizTel = "+" + bizPhone();
    var site = "www.blessconcandy.com";
    var email = (typeof CFG !== "undefined" && CFG.email) || "blessconcandy@gmail.com";
    var totalQty = o.lines.reduce(function (s, l) { return s + (Number(l.qty) || 0); }, 0);

    /* ---------- header: gradient, soft circles, confetti, logo ---------- */
    gradBand(0, 0, W, 48);
    alpha(0.13); fill(WHITE); doc.circle(W - 14, 6, 26, "F"); doc.circle(28, 52, 20, "F"); doc.circle(W / 2 + 10, -4, 16, "F"); alpha(1);
    fill(GOLD); [[W - 52, 11, 1.6], [W - 38, 40, 1.2], [92, 9, 1.1], [100, 41, 1.5], [W - 70, 30, 0.9]].forEach(function (d) { doc.circle(d[0], d[1], d[2], "F"); });
    alpha(0.45); fill(WHITE); [[88, 30, 1.2], [W - 28, 36, 1.8], [W - 90, 8, 1]].forEach(function (d) { doc.circle(d[0], d[1], d[2], "F"); }); alpha(1);
    /* logo badge */
    alpha(0.25); fill([60, 0, 25]); doc.roundedRect(M + 0.8, 10.8, 68, 28, 14, 14, "F"); alpha(1);
    fill(WHITE); doc.roundedRect(M, 10, 68, 28, 14, 14, "F");
    if (logo) {
      var bw = 56, bh = 20, k = Math.min(bw / logo.w, bh / logo.h), lw = logo.w * k, lh = logo.h * k;
      doc.addImage(logo.data, "PNG", M + (68 - lw) / 2, 10 + (28 - lh) / 2, lw, lh);
    } else {
      font("bold", 18); ink(PINK); doc.text("Blesscon Candy", M + 34, 27, { align: "center" });
    }
    font("bold", 19); ink(WHITE); doc.text("ORDER RECEIPT", W - M, 19, { align: "right" });
    stroke(WHITE); doc.setLineWidth(0.4); alpha(0.5); doc.line(W - M - 64, 23, W - M, 23); alpha(1);
    font("normal", 8); doc.text("ORDER NO.", W - M, 29, { align: "right" });
    font("bold", 12); doc.text(pt(o.id), W - M, 35, { align: "right" });
    font("normal", 9.5); doc.text(pt(o.date), W - M, 41, { align: "right" });

    /* ---------- customer / delivery cards ---------- */
    var cardW = (CW - 6) / 2, tw = cardW - 12;
    font("bold", 10.5); var nameLines = doc.splitTextToSize(pt(o.customer.name) || "-", tw).slice(0, 2);
    var locLines = doc.splitTextToSize(pt(o.location) || "-", tw).slice(0, 2);
    font("normal", 9); var addrLines = doc.splitTextToSize(pt(o.address), tw).slice(0, 3);
    var phoneTxt = pt(o.customer.phone);
    var h1 = 14 + nameLines.length * 5 + (phoneTxt ? 5 : 0), h2 = 14 + locLines.length * 5 + addrLines.length * 4.3;
    var cardH = Math.max(h1, h2, 26), cy = 56;
    function card(x, label) {
      alpha(0.08); fill(PINKD); doc.roundedRect(x + 0.6, cy + 0.9, cardW, cardH, 3, 3, "F"); alpha(1);
      fill(WHITE); stroke(LINE); doc.setLineWidth(0.3); doc.roundedRect(x, cy, cardW, cardH, 3, 3, "FD");
      fill(PINK); doc.roundedRect(x, cy + 3, 1.8, cardH - 6, 0.9, 0.9, "F");
      font("bold", 7.5); ink(PINK); doc.text(label, x + 7, cy + 7);
    }
    card(M, "CUSTOMER"); card(M + cardW + 6, "DELIVER TO");
    font("bold", 10.5); ink(INK); doc.text(nameLines, M + 7, cy + 13);
    if (phoneTxt) { font("normal", 9); ink(MUTED); doc.text(phoneTxt, M + 7, cy + 13 + nameLines.length * 5); }
    var rx = M + cardW + 6 + 7;
    font("bold", 10.5); ink(INK); doc.text(locLines, rx, cy + 13);
    font("normal", 9); ink(MUTED); doc.text(addrLines, rx, cy + 13 + locLines.length * 5);

    /* ---------- items table ---------- */
    var cNum = M + 6, cName = M + 15, nameW = 74, cUnit = M + 130, cQty = M + 146, cTot = W - M - 4;
    function tableHead(y) {
      fill(PINKD); doc.roundedRect(M, y, CW, 9.5, 2.5, 2.5, "F");
      font("bold", 7.8); ink(WHITE);
      doc.text("#", cNum, y + 6.2, { align: "center" }); doc.text("PRODUCT", cName, y + 6.2);
      doc.text("UNIT PRICE", cUnit, y + 6.2, { align: "right" }); doc.text("QTY", cQty, y + 6.2, { align: "center" });
      doc.text("TOTAL", cTot, y + 6.2, { align: "right" });
      return y + 11;
    }
    function pageFooter() {
      gradBand(0, H - 21, W, 21);
      fill(GOLD); doc.circle(M + 2, H - 10.5, 1.3, "F"); doc.circle(W - M - 2, H - 10.5, 1.3, "F");
      font("bold", 10.5); ink(WHITE); doc.text("Thank you for ordering from Blesscon Candy!", W / 2, H - 13, { align: "center" });
      font("normal", 8.3); doc.text("WhatsApp " + bizTel + "   |   " + site + "   |   " + email, W / 2, H - 7.5, { align: "center" });
    }
    function miniHead() {
      gradBand(0, 0, W, 12); font("bold", 9.5); ink(WHITE);
      doc.text("Blesscon Candy", M, 7.8); doc.text("Order " + pt(o.id), W - M, 7.8, { align: "right" });
    }
    var y = tableHead(cy + cardH + 9);
    o.lines.forEach(function (ln, i) {
      font("bold", 9.5);
      var nm = doc.splitTextToSize(pt(ln.name), nameW);
      var rowH = nm.length * 4.6 + 4.2 + 5;
      if (y + rowH > H - 30) { pageFooter(); doc.addPage(); miniHead(); y = tableHead(18); }
      if (i % 2 === 0) { fill(BG); doc.rect(M, y - 1, CW, rowH, "F"); }
      var ty = y + 5;
      font("normal", 9.5); ink(MUTED); doc.text(String(i + 1), cNum, ty + 0.6, { align: "center" });
      font("bold", 9.5); ink(INK); doc.text(nm, cName, ty + 0.6);
      font("normal", 8); ink(MUTED); doc.text(pt(ln.pack), cName, ty + 0.6 + nm.length * 4.6 - 0.4);
      font("normal", 9.5); ink(INK); doc.text(pt(money(ln.unit)), cUnit, ty + 0.6, { align: "right" });
      fill(SOFT); doc.roundedRect(cQty - 6, ty - 3.6, 12, 6.2, 3.1, 3.1, "F");
      font("bold", 9); ink(PINKD); doc.text(String(ln.qty), cQty, ty + 0.8, { align: "center" });
      font("bold", 9.5); ink(INK); doc.text(pt(money(ln.total)), cTot, ty + 0.6, { align: "right" });
      y += rowH;
    });
    stroke(LINE); doc.setLineWidth(0.3); doc.line(M, y, W - M, y);

    /* ---------- totals + thank-you note ---------- */
    font("normal", 9);
    var delTxt = o.delivery != null ? pt(money(o.delivery)) : pt(o.deliveryNote || "Confirmed by our team");
    var delLines = doc.splitTextToSize(delTxt, 46);
    var totH = 8 + 8 + delLines.length * 4.4 + 4 + 14 + 6;
    if (y + totH + 14 > H - 28) { pageFooter(); doc.addPage(); miniHead(); y = 18; }
    var ty0 = y + 8, bx = W - M - 86;
    /* note card (left) */
    var noteLines = doc.splitTextToSize("Our team will confirm your order, delivery and payment details with you on WhatsApp. Please keep this receipt for your records.", 70);
    fill(BG); stroke(LINE); doc.roundedRect(M, ty0, 88, totH, 3, 3, "FD");
    font("bold", 11); ink(PINKD); doc.text("Thank you!", M + 6, ty0 + 9);
    font("normal", 8.6); ink(MUTED); doc.text(noteLines, M + 6, ty0 + 15);
    font("bold", 8.2); ink(PINK); doc.text(totalQty + (totalQty === 1 ? " item" : " items") + " in this order", M + 6, ty0 + totH - 5);
    /* totals (right) */
    font("normal", 9.5); ink(MUTED); doc.text("Subtotal", bx, ty0 + 6);
    font("bold", 9.5); ink(INK); doc.text(pt(money(o.subtotal)), W - M, ty0 + 6, { align: "right" });
    font("normal", 9.5); ink(MUTED); doc.text("Delivery", bx, ty0 + 14);
    font(o.delivery != null ? "bold" : "normal", o.delivery != null ? 9.5 : 8.3); ink(INK); doc.text(delLines, W - M, ty0 + 14, { align: "right" });
    var gy = ty0 + 14 + delLines.length * 4.4 + 2;
    alpha(0.18); fill(PINKD); doc.roundedRect(bx - 4 + 0.6, gy + 0.9, 90, 14, 4, 4, "F"); alpha(1);
    fill(PINK); doc.roundedRect(bx - 4, gy, 90, 14, 4, 4, "F");
    font("bold", 9.5); ink(WHITE); doc.text("TOTAL PAYABLE", bx, gy + 8.8);
    font("bold", 13); doc.text(pt(money(o.grand)), W - M - 3, gy + 9, { align: "right" });

    /* ---------- footer on the last page + page numbers ---------- */
    pageFooter();
    var n = doc.getNumberOfPages();
    if (n > 1) for (var p = 1; p <= n; p++) { doc.setPage(p); font("normal", 7); ink(WHITE); doc.text("Page " + p + " of " + n, W - M, H - 2.2, { align: "right" }); }

    var blob = doc.output("blob"), name = "Blesscon-Receipt-" + String(o.id).replace(/[^\w-]/g, "") + ".pdf";
    var file = null;
    try { file = new File([blob], name, { type: "application/pdf" }); } catch (e) { /* very old browsers: share unavailable, download still works */ }
    return { blob: blob, file: file, name: name };
  });
}
function saveBlob(pdf) {
  var url = URL.createObjectURL(pdf.blob), a = document.createElement("a");
  a.href = url; a.download = pdf.name; a.rel = "noopener"; document.body.appendChild(a); a.click();
  setTimeout(function () { a.remove(); URL.revokeObjectURL(url); }, 4000);
}
function note(m) { if (typeof toast === "function") toast(m); }
/* short chat text used when the PDF has to be attached by hand */
function waIntro(o) {
  return "*BLESSCON CANDY - ORDER RECEIPT*\nOrder: " + o.id + "  |  " + o.date + "\nTOTAL PAYABLE: " + money(o.grand) + "\n(PDF receipt attached)";
}

function open(o) {
  close();
  var el = document.createElement("div");
  el.className = "inv-wrap"; el.id = "bcInv"; el.setAttribute("aria-label", "Order invoice");
  var rows = o.lines.map(function (ln, i) {
    return '<tr><td class="c">' + (i + 1) + '</td>' +
      '<td><b>' + esc(ln.name) + '</b><small>' + esc(ln.pack) + '</small></td>' +
      '<td class="r">' + money(ln.unit) + '</td>' +
      '<td class="c">' + ln.qty + '</td>' +
      '<td class="r"><b>' + money(ln.total) + '</b></td></tr>';
  }).join("");
  var delRow = o.delivery != null
    ? '<div><span>Delivery</span><b>' + money(o.delivery) + '</b></div>'
    : '<div><span>Delivery</span><b>' + esc(o.deliveryNote || "Confirmed by our team") + '</b></div>';
  el.innerHTML =
    '<div class="inv-card" role="dialog" aria-modal="true">' +
      '<div class="inv-head">' +
        '<div class="inv-brand"><span class="inv-logo"><img src="' + LOGO_FALLBACK + '" alt="Blesscon Candy"></span><div><b>Blesscon Candy</b><small>Order Receipt</small></div></div>' +
        '<div class="inv-meta"><b>' + esc(o.id) + '</b><div>' + esc(o.date) + '</div></div>' +
      '</div>' +
      '<div class="inv-to">' +
        '<div><small>Customer</small><b>' + esc(o.customer.name) + '</b><span>' + esc(o.customer.phone || "") + '</span></div>' +
        '<div><small>Deliver to</small><b>' + esc(o.location || "-") + '</b><span>' + esc(o.address || "") + '</span></div>' +
      '</div>' +
      '<div class="inv-tblwrap"><table class="inv-tab">' +
        '<thead><tr><th>#</th><th>Product</th><th>Unit Price</th><th>Qty</th><th>Total</th></tr></thead>' +
        '<tbody>' + rows + '</tbody></table></div>' +
      '<div class="inv-tots">' +
        '<div><span>Subtotal</span><b>' + money(o.subtotal) + '</b></div>' + delRow +
        '<div class="inv-grand"><span>Total Payable</span><b>' + money(o.grand) + '</b></div>' +
      '</div>' +
      '<div class="inv-foot">Thank you for your order! Questions? WhatsApp +' + bizPhone() + ' · www.blessconcandy.com</div>' +
      '<div class="inv-cta">' +
        '<button type="button" class="btn wa" id="invSendWa">Send to my WhatsApp number</button>' +
        '<button type="button" class="btn alt" id="invShare" hidden>Share PDF file</button>' +
        '<button type="button" class="btn alt" id="invPrint">Download PDF</button>' +
        '<button type="button" class="btn ghostbtn" id="invClose">Close</button>' +
      '</div>' +
    '</div>';
  document.body.appendChild(el);
  document.body.style.overflow = "hidden";
  loadLogo().then(function (l) { var im = el.querySelector(".inv-logo img"); if (l && im) im.src = l.data; });
  var d = waDigits(o.customer.phone);
  var pdfP = null;
  function getPdf() { if (!pdfP) pdfP = buildPdf(o); return pdfP; }
  getPdf().catch(function () { /* handled when a button is pressed */ });   /* build while the customer reads the invoice, so Share fires instantly */
  var waBtn = el.querySelector("#invSendWa"), dlBtn = el.querySelector("#invPrint");
  function textFallback() {
    if (!d) { note("No WhatsApp number found in your order"); return; }
    window.open("https://wa.me/" + d + "?text=" + encodeURIComponent(receiptText(o)), "_blank");
  }
  /* main button: save the PDF, then open WhatsApp chat with the number typed at checkout */
  waBtn.onclick = function () {
    if (!d) { note("No WhatsApp number found in your order"); return; }
    getPdf().then(function (pdf) {
      saveBlob(pdf);
      note("PDF saved. Tap the attach (clip) icon in WhatsApp and choose it.");
      window.open("https://wa.me/" + d + "?text=" + encodeURIComponent(waIntro(o)), "_blank");
    }).catch(function () {
      note("Could not build the PDF - sending the receipt as text instead");
      textFallback();
    });
  };
  /* optional button (phones/tablets that can share files): attaches the PDF itself via the share sheet */
  var shBtn = el.querySelector("#invShare");
  if (navigator.canShare && shBtn) {
    getPdf().then(function (pdf) {
      if (pdf.file && navigator.canShare({ files: [pdf.file] })) shBtn.hidden = false;
    }).catch(function () {});
    shBtn.onclick = function () {
      getPdf().then(function (pdf) {
        return navigator.share({ files: [pdf.file], title: "Blesscon Candy receipt " + o.id, text: "Blesscon Candy order receipt " + o.id });
      }).catch(function () {});
    };
  }
  dlBtn.onclick = function () {
    getPdf().then(saveBlob).catch(function () { window.print(); });
  };
  el.querySelector("#invClose").onclick = close;
  el.addEventListener("click", function (e) { if (e.target === el) close(); });
}
function close() {
  var el = document.getElementById("bcInv");
  if (el) el.remove();
  document.body.style.overflow = "";
}
window.BCInvoice = { open: open, close: close };
})();
